inline bool fromJson(JsonVariantConst src, HelloMessageData& out) {
    if (src.isNull()) return false;
    if (!src["deviceId"].is<const char*>()) return false;
    out.deviceId = src["deviceId"].as<const char*>();
    if (!src["firmware"].is<const char*>()) return false;
    out.firmware = src["firmware"].as<const char*>();
    if (!src["board"].is<const char*>()) return false;
    out.board = src["board"].as<const char*>();
    if (!src["timezone"].isNull()) {
      out.hasTimezone = true;
  out.timezone = src["timezone"].as<const char*>();
    } else {
      out.hasTimezone = false;
    }
out.capabilities.clear();
for (JsonVariantConst item : src["capabilities"].as<JsonArrayConst>()) out.capabilities.push_back(item.as<const char*>());
    return true;
}

inline void toJson(const HelloMessageData& v, JsonObject dst) {
    dst["deviceId"] = v.deviceId;
    dst["firmware"] = v.firmware;
    dst["board"] = v.board;
    if (v.hasTimezone) {
      dst["timezone"] = v.timezone;
    }
    JsonArray array = dst["capabilities"].to<JsonArray>();
    for (const auto& element : v.capabilities) {
      array.add(element);
    }
}

